import fs from 'node:fs';import vm from 'node:vm';import assert from 'node:assert/strict';import crypto from 'node:crypto';import {spawnSync}from 'node:child_process';import{toolDependency}from './refresh-deps.mjs';
const manifest=JSON.parse(fs.readFileSync('games/shared/audio-v3/manifest.json')),hashes=new Set(),report=[];assert.equal(manifest.tracks.length,19);
for(const t of manifest.tracks){const file='games/shared/audio-v3/'+t.file,bytes=fs.readFileSync(file);hashes.add(crypto.createHash('sha256').update(bytes).digest('hex'));const r=spawnSync(toolDependency('ffmpeg-static'),['-v','error','-i',file,'-f','f32le','-ac','1','-ar','16000','pipe:1'],{maxBuffer:24e6});assert.equal(r.status,0,r.stderr?.toString());const samples=new Float32Array(r.stdout.buffer,r.stdout.byteOffset,r.stdout.length/4);let sum=0,peak=0;for(const v of samples){sum+=v*v;peak=Math.max(peak,Math.abs(v));}const rms=Math.sqrt(sum/samples.length);assert(samples.length/16000>=45);assert(rms>.01&&rms<.5);assert(peak<1.05);report.push({id:t.id,seconds:samples.length/16000,rms,peak,bytes:bytes.length});}
assert.equal(hashes.size,19);
let made=[],events={};class Audio{constructor(src){this.src=src;this.paused=true;this.events={};made.push(this)}addEventListener(k,f){this.events[k]=f}pause(){this.paused=true}play(){this.paused=false;return Promise.resolve()}}
const window={},document={currentScript:{src:'https://example.test/games/shared/audio-engine-v2.js'},hidden:false,querySelectorAll:()=>[],addEventListener:(k,f)=>events[k]=f};vm.runInNewContext(fs.readFileSync('games/shared/audio-engine-v2.js','utf8'),{window,document,Audio,URL,performance:{now:()=>1000},addEventListener:(k,f)=>events[k]=f});
for(const t of manifest.tracks){const p=window.CxQAudioEngine.create({id:t.id,tracks:['audio-v2/'+t.id+'.mp3']});events.pointerdown();p.sync();await Promise.resolve();assert.match(p.status().source,new RegExp('audio-v3/'+t.id+'\\.mp3'));const src=p.status().source;p.tracks(['audio-v2/'+t.id+'.mp3']);assert.equal(p.status().source,src);p.dispose();}
for(const id of ['poker','fairytale-defense','heartlight-duel']){const p=window.CxQAudioEngine.create({id,tracks:['regional-'+id+'.mp3','audio-v2/'+id+'.mp3']});p.sync();await Promise.resolve();assert.match(p.status().source,new RegExp('regional-'+id));made.at(-1).events.ended();await Promise.resolve();assert.match(p.status().source,new RegExp('audio-v3/'+id));const source=p.status().source;p.tracks(['regional-'+id+'.mp3','audio-v2/'+id+'.mp3']);assert.equal(p.status().source,source);p.dispose();}
fs.writeFileSync('outputs/integrated-refresh-20261009/audio-verification.json',JSON.stringify(report,null,2));console.log('PASS 19 different tracks decode, audible RMS, clipping budget, first gesture and repeated playlist sync');
